const crypto = require('crypto');

const body = $json.body ?? $json;
const headers = $json.headers ?? {};
const secret = $env.KOMMO_WEBHOOK_SECRET || '';
const incomingSig = (headers['x-kommo-signature'] || headers['x-signature'] || '').toString().replace(/^sha256=/i, '');

const rawBody = JSON.stringify(body);
let signatureValid = true;
if (secret) {
  const calculated = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
  signatureValid = incomingSig.length > 0 && crypto.timingSafeEqual(Buffer.from(calculated, 'hex'), Buffer.from(incomingSig, 'hex'));
}

const lead = body.lead || {};
const task = body.task || {};
const actor = body.actor || {};
const eventType = body.event_type || (task.completed_at ? 'task.completed' : task.id ? 'task.updated' : lead.from_stage_id || lead.to_stage_id ? 'lead.stage_changed' : lead.created_at ? 'lead.created' : 'lead.updated');
const eventAt = body.event_time || task.updated_at || lead.updated_at || new Date().toISOString();
const leadId = Number(lead.id || task.lead_id || 0) || null;
const pipelineId = Number(lead.pipeline_id || 0) || null;
const fromStageId = Number(lead.from_stage_id || 0) || null;
const toStageId = Number(lead.to_stage_id || lead.stage_id || 0) || null;
const taskId = Number(task.id || 0) || null;

const stable = JSON.stringify({ eventType, eventAt, leadId, pipelineId, fromStageId, toStageId, taskId, status: lead.status || task.status || null });
const eventId = String(body.event_id || crypto.createHash('sha256').update(stable).digest('hex'));

return [{
  json: {
    signatureValid,
    rawBody,
    body,
    normalized: {
      source: 'kommo',
      event_type: eventType,
      event_id: eventId,
      lead_id: leadId,
      event_at: new Date(eventAt).toISOString(),
      pipeline_id: pipelineId,
      from_stage_id: fromStageId,
      to_stage_id: toStageId,
      owner_id: Number(lead.owner_id || task.owner_id || 0) || null,
      actor_type: actor.type || null,
      actor_id: Number(actor.id || 0) || null,
      status: lead.status || task.status || null,
      due_at: task.due_at ? new Date(task.due_at).toISOString() : null,
      completed_at: task.completed_at ? new Date(task.completed_at).toISOString() : null,
      price: lead.price ?? null,
      lost_reason_id: Number(lead.lost_reason_id || 0) || null,
      tags: Array.isArray(lead.tags) ? lead.tags : [],
      source: lead.source || lead.utm_source || null,
      campaign: lead.campaign || lead.utm_campaign || null,
      channel: lead.channel || null,
      task_id: taskId,
      lead_created_at: lead.created_at ? new Date(lead.created_at).toISOString() : null,
      lead_updated_at: lead.updated_at ? new Date(lead.updated_at).toISOString() : null
    }
  }
}];

